const body = $input.first().json.body;

const required = ['filename', 'scheduled_date'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  return [{ json: { error: `Missing fields: ${missing.join(', ')}`, valid: false } }];
}

const platforms = body.platforms || ['instagram', 'tiktok', 'youtube'];
const validPlatforms = ['instagram', 'tiktok', 'youtube'];
const invalidPlatforms = platforms.filter(p => !validPlatforms.includes(p));
if (invalidPlatforms.length > 0) {
  return [{ json: { error: `Invalid platforms: ${invalidPlatforms.join(', ')}`, valid: false } }];
}

const scheduleDate = new Date(body.scheduled_date);
if (isNaN(scheduleDate.getTime())) {
  return [{ json: { error: 'Invalid scheduled_date format', valid: false } }];
}

return [{
  json: {
    valid: true,
    filename: body.filename,
    scheduled_date: body.scheduled_date,
    caption_override: body.caption_override || null,
    platforms,
  }
}];

const item = $input.first().json;
const fs = require('fs');

const calendarPath = '/data/content_calendar.json';
let calendar = [];
try {
  const raw = fs.readFileSync(calendarPath, 'utf8');
  calendar = JSON.parse(raw);
} catch (e) {
  calendar = [];
}

const entry = {
  id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
  filename: item.filename,
  scheduled_date: item.scheduled_date,
  caption_override: item.caption_override,
  platforms: item.platforms,
  status: 'scheduled',
  created_at: new Date().toISOString(),
};

calendar.push(entry);
calendar.sort((a, b) => new Date(a.scheduled_date) - new Date(b.scheduled_date));

fs.writeFileSync(calendarPath, JSON.stringify(calendar, null, 2));

return [{ json: { success: true, entry } }];
